// Generated by Automated Quality Gate; review before merging.
const { 
  add, 
  subtract, 
  multiply, 
  divide, 
  calculatePercentage, 
  modulo, 
  absoluteDifference 
} = require('../../src/math');

describe('Math Utility Functions', () => {
  
  describe('Input Validation', () => {
    const invalidInputs = ['1', null, undefined, NaN, Infinity, -Infinity];
    
    test.each([
      ['add', add],
      ['subtract', subtract],
      ['multiply', multiply],
      ['divide', divide],
      ['calculatePercentage', calculatePercentage],
      ['modulo', modulo],
      ['absoluteDifference', absoluteDifference]
    ])('%s should throw error for invalid inputs', (_, fn) => {
      invalidInputs.forEach(input => {
        expect(() => fn(input, 1)).toThrow(TypeError);
        expect(() => fn(1, input)).toThrow(TypeError);
      });
    });
  });

  describe('add', () => {
    test('should correctly add two numbers', () => {
      expect(add(2, 3)).toBe(5);
      expect(add(-1, -1)).toBe(-2);
      expect(add(0, 0)).toBe(0);
    });
  });

  describe('subtract', () => {
    test('should subtract and normalize -0 to 0', () => {
      expect(subtract(5, 3)).toBe(2);
      expect(subtract(0, 0)).toBe(0);
      expect(Object.is(subtract(0, 0), -0)).toBe(false);
    });
  });

  describe('multiply', () => {
    test('should multiply and normalize -0 to 0', () => {
      expect(multiply(2, 3)).toBe(6);
      expect(multiply(-2, 0)).toBe(0);
      expect(Object.is(multiply(-2, 0), -0)).toBe(false);
    });
  });

  describe('divide', () => {
    test('should divide correctly', () => {
      expect(divide(6, 2)).toBe(3);
    });

    test('should throw error on division by zero', () => {
      expect(() => divide(5, 0)).toThrow('Cannot divide by zero');
      expect(() => divide(5, -0)).toThrow('Cannot divide by zero');
    });
  });

  describe('calculatePercentage', () => {
    test('should calculate percentage correctly', () => {
      expect(calculatePercentage(50, 200)).toBe(25);
    });

    test('should return 0 when total is 0', () => {
      expect(calculatePercentage(50, 0)).toBe(0);
    });
  });

  describe('modulo', () => {
    test('should calculate mathematical modulo', () => {
      expect(modulo(7, 4)).toBe(3);
      expect(modulo(-7, 4)).toBe(1);
    });

    test('should throw error on modulo by zero', () => {
      expect(() => modulo(5, 0)).toThrow('Cannot modulo by zero');
    });
  });

  describe('absoluteDifference', () => {
    test('should return the absolute difference', () => {
      expect(absoluteDifference(5, 2)).toBe(3);
      expect(absoluteDifference(2, 5)).toBe(3);
    });
  });

});
